import{z as i,x as p,o,c as B,q as l,j as t,D as n,d as r,s,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"OpenMP 与 MPI 的直觉","description":"","frontmatter":{"title":"OpenMP 与 MPI 的直觉","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/par-openmp-mpi.md","filePath":"cs/par-openmp-mpi.md","lastUpdated":1791413859000}'),A={name:"cs/par-openmp-mpi.md"};function P(c,a,m,u,M,f){const E=p("Mermaid");return o(),B("div",null,[a[2]||(a[2]=l('<h1 id="openmp-与-mpi-的直觉" tabindex="-1">OpenMP 与 MPI 的直觉 <a class="header-anchor" href="#openmp-与-mpi-的直觉" aria-label="Permalink to &quot;OpenMP 与 MPI 的直觉&quot;">​</a></h1><div class="epigraph"><p>OpenMP 把并行写成给编译器的标注，MPI 把并行写成进程之间的消息；选哪套不是口味，是「内存共享到哪一层」的决定。</p><footer>—— 据 MPI Forum, MPI: A Message-Passing Interface Standard, 1994；OpenMP Architecture Review Board 规范整理</footer></div><p><a href="/cs/par-pram-to-practice">上一课</a>把 PRAM 的四条假设逐项翻成真实成本：\\(P\\) 有限、访存分层、同步收费。缺口是落点：真要写并行程序，共享内存这条线怎么写、无共享那条线怎么写。OpenMP 与 MPI 分别是两套直觉的主流化身：前者把线程组藏进编译器标注，后者把世界切成靠消息说话的进程。底层机制已有课垫底——<a href="/cs/thread-shared-addr">线程与共享地址空间</a>给过共享侧，<a href="/cs/fork">fork</a> 给过进程侧——本课站在它们之上谈编程模型，不重讲切换与页表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>共享内存模型的全部成本都压在「哪些访问会撞」上。OpenMP 的 <code>parallel for</code> 把循环切块分给线程组，写的人必须自己声明撞在哪里：reduction 声明「各攒各的、出口合并」，barrier 声明「在此对齐」，critical 圈住残余的共享写。漏声明不是报错，而是 data race——<a href="/cs/language-memory-model">语言内存模型与 data race</a> 的 UB 结论直接适用。MPI 一侧没有撞的机会，因为根本没有共享：每个 rank 对自己的地址空间负责，一切交换显式写进 send/recv；代价是「把字节搬过网络」从此成为你代码的一部分。错法：把 <code>MPI_Send</code> 当普通函数调用——它的返回只表示本地缓冲完成，不等对端收到。</p><p><span class="marginnote">直觉类比：<code>MPI_Send</code> 返回像「信已经塞进邮筒」，不代表对方拆了信；大消息走 rendezvous 更像寄大件快递——快递员先打电话确认你在家（对端张贴了 recv）才肯发货。所以「发了」与「被收」之间隔着一整套运行时协议。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两套直觉各记一句。OpenMP：「共享在，同步要逐处声明」——调度子句 static/dynamic/guided 控制怎么切块，块大小就是负载均衡与局部性的折中。MPI：「边界画死，移动算钱」——先想清楚数据属于谁，再想谁要找谁；broadcast、reduce、allreduce 把常见通信拓扑一次说清。选型随之而定：问题能切成大方块、通信比小，MPI 顺；细粒度共享、负载不规则，OpenMP 与线程顺；大机器两者混用——rank 之间 MPI，rank 之内 OpenMP。</p>',8)),(o(),t(d,null,{default:n(()=>[s(E,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%E5%B9%B6%E8%A1%8C%E7%AE%97%E6%B3%95%22%5D%20--%3E%20SH%5B%22%E5%85%B1%E4%BA%AB%E5%9C%B0%E5%9D%80%E7%A9%BA%E9%97%B4%22%5D%0A%20%20SRC%20--%3E%20NS%5B%22%E6%97%A0%E5%85%B1%E4%BA%AB%E6%9C%BA%E5%99%A8%22%5D%0A%20%20SH%20--%3E%20OMP%5B%22%E7%BA%BF%E7%A8%8B%E7%BB%84%20%2B%20%E9%80%90%E5%A4%84%E5%A3%B0%E6%98%8E%E5%90%8C%E6%AD%A5%22%5D%0A%20%20NS%20--%3E%20MPIR%5B%22%E8%BF%9B%E7%A8%8B%20%2B%20%E6%98%BE%E5%BC%8F%E6%B6%88%E6%81%AF%22%5D%0A%20%20OMP%20--%3E%20FJ%5B%22fork-join%E3%80%81reduction%E3%80%81barrier%22%5D%0A%20%20MPIR%20--%3E%20COLL%5B%22send%2Frecv%20%E4%B8%8E%E9%9B%86%E5%90%88%E9%80%9A%E4%BF%A1%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[r("两套各有一笔机制账。OpenMP 的线程组是 fork-join：进入并行区派生、出口汇合；reduction 的合并在出口做，加法次序不定——浮点结果与串行版本逐位不同，这是并行的正常代价，不是 bug。MPI 的消息靠信封匹配（通信子、源、tag）；大消息走 rendezvous，对端没有张贴接收就把发送方拖住，「发了」与「被收」之间隔着一个运行时。集合通信在进程树上折叠：allreduce 的通信量随 \\(P\\) 按树深对数增长，不是 \\(P\\) 倍带宽——大模型张量并行每层要付的 allreduce 账，用的正是这一条直觉（见"),e("a",{href:"/llm/tensor-parallel"},"张量并行"),r("），同一本账换了个领域记账。")],-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"数字实例：64 个 rank 做 allreduce，树形折叠只需 \\(\\log_2 64 = 6\\) 步，而不是 64 份带宽；rank 再翻倍到 128，也只多一步。这就是「按树深对数增长」的意思——集合通信能把通信账从 \\(P\\) 压到 \\(\\log P\\)，深训练里省的就是这个。")],-1)),a[6]||(a[6]=e("p",null,"大消息的 rendezvous 把「发了」与「被收」隔开的全过程，单独画一遍——它回答的是握手时序问题，与上面那张选型图不同。",-1)),(o(),t(d,null,{default:n(()=>[s(E,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E5%8F%91%E9%80%81%E6%96%B9%20MPI_Send%20%E5%A4%A7%E6%B6%88%E6%81%AF%22%5D%20--%3E%20B%5B%22%E5%8F%91%20rendezvous%20%E8%AF%B7%E6%B1%82%E5%90%8E%E6%8C%82%E8%B5%B7%22%5D%0A%20%20C%5B%22%E5%AF%B9%E7%AB%AF%E5%BC%A0%E8%B4%B4%E5%8C%B9%E9%85%8D%E7%9A%84%20recv%22%5D%20--%3E%20D%5B%22%E8%BF%90%E8%A1%8C%E6%97%B6%E6%8F%A1%E6%89%8B%E7%A1%AE%E8%AE%A4%22%5D%0A%20%20B%20--%3E%20D%0A%20%20D%20--%3E%20E%5B%22%E6%95%B0%E6%8D%AE%E7%9C%9F%E6%AD%A3%E6%90%AC%E8%BF%90%22%5D%0A%20%20E%20--%3E%20F%5B%22Send%20%E6%89%8D%E8%BF%94%E5%9B%9E%3A%20%E6%94%B6%E5%88%B0%E6%89%8D%E7%AE%97%E6%95%B0%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote"><code>#pragma omp parallel for reduction(+:s)</code> 的出口合并次序不确定：同一程序两次运行可以逐位不同。要可复现，得固定切块并自己写树形归约，而不是指望编译器替你保证。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 GPU 直通与 CUDA-aware MPI；不写无锁与 CAS（后面 lock-free 课）；扩展性的实验语言——强扩展、弱扩展——已有 <a href="/cs/gustafson-law">Gustafson 定律</a>与强扩展弱扩展两课承担，这里不立基准。OpenMP 的任务与依赖子句归下一课的「任务并行」视角，本课停在循环级。两套系统的实现细节——线程池、缓冲管理、拓扑感知的 rank 放置——也不展开：本课只立直觉与记账方式。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OpenMP 把并行写成编译器标注：共享在，同步逐处声明，出口合并。</li><li>MPI 把并行写成显式消息：数据归属与通信都在代码里，字节移动算钱。</li><li>浮点 reduction 次序不定是代价不是 bug；可复现要自己固定归约树。</li><li>选型看通信比与粒度；大机器常用 MPI 之间、OpenMP 之内的混用。</li><li>出处：MPI Forum 标准，1994；OpenMP ARB 规范；Herlihy and Shavit, The Art of Multiprocessor Programming 第 1 章的共享与分布式对照。</li></ul><p><span class="marginnote">为什么选型先看「通信比」：拿矩阵乘举例，\\(n=1000\\) 时要搬的数据是 \\(O(n^2)\\) 量级（百万个元素），要做的计算是 \\(O(n^3)\\) 量级（十亿次乘加）——每搬一个字节能换上千次运算，通信「不亏」，切大方块交给 MPI 划算。反过来若每步计算都要等一小口数据，共享内存的细粒度路线才合身。</span></p>',6))])}const I=i(A,[["render",P]]);export{D as __pageData,I as default};
